    @Test
    public void testIsNumber() {
        // --- Valid Numbers ---

        // Positive integers
        assertTrue("Expected '123' to be a number", Strings.isNumber("123"));
        assertTrue("Expected '0' to be a number", Strings.isNumber("0"));
        assertTrue("Expected '9876543210' to be a number", Strings.isNumber("9876543210"));

        // Negative integers (with leading hyphen)
        assertTrue("Expected '-123' to be a number", Strings.isNumber("-123"));
        assertTrue("Expected '-0' to be a number", Strings.isNumber("-0"));
        assertTrue("Expected '-9' to be a number", Strings.isNumber("-9"));

        // Decimal numbers (with at most one decimal point)
        assertTrue("Expected '1.23' to be a number", Strings.isNumber("1.23"));
        assertTrue("Expected '0.0' to be a number", Strings.isNumber("0.0"));
        assertTrue("Expected '-1.23' to be a number", Strings.isNumber("-1.23"));
        assertTrue("Expected '1.' to be a number", Strings.isNumber("1.")); // Valid according to intention
        assertTrue("Expected '-1.' to be a number", Strings.isNumber("-1.")); // Valid according to intention

        // Special case: Single hyphen
        assertTrue("Expected '-' to be a number as per method intention", Strings.isNumber("-"));

        // --- Invalid Numbers ---

        // Null or Empty strings
        assertFalse("Expected null to not be a number", Strings.isNumber(null));
        assertFalse("Expected empty string '' to not be a number", Strings.isNumber(""));

        // Contains non-digit, non-hyphen, non-decimal point characters
        assertFalse("Expected 'abc' to not be a number", Strings.isNumber("abc"));
        assertFalse("Expected '123a' to not be a number", Strings.isNumber("123a"));
        assertFalse("Expected 'a123' to not be a number", Strings.isNumber("a123")); // Fails: first char is not digit or hyphen
        assertFalse("Expected '1.2a' to not be a number", Strings.isNumber("1.2a"));
        assertFalse("Expected '$1.23' to not be a number", Strings.isNumber("$1.23"));
        assertFalse("Expected '1,234' to not be a number", Strings.isNumber("1,234"));
        assertFalse("Expected ' ' (space) to not be a number", Strings.isNumber(" "));
        assertFalse("Expected '  1' to not be a number", Strings.isNumber("  1"));

        // Multiple hyphens or hyphen not at the beginning
        assertFalse("Expected '--123' to not be a number", Strings.isNumber("--123"));
        assertFalse("Expected '12-3' to not be a number", Strings.isNumber("12-3"));
        assertFalse("Expected '-1-2' to not be a number", Strings.isNumber("-1-2"));

        // Multiple decimal points
        assertFalse("Expected '1.2.3' to not be a number", Strings.isNumber("1.2.3"));
        assertFalse("Expected '-1.2.3' to not be a number", Strings.isNumber("-1.2.3"));

        // Decimal point at the beginning (without leading digit or hyphen)
        assertFalse("Expected '.123' to not be a number", Strings.isNumber(".123")); // Fails: first char is not digit or hyphen
        assertFalse("Expected '.' to not be a number", Strings.isNumber(".")); // Fails: first char is not digit or hyphen
    }
